<?php
declare(strict_types=1);
/** All queue, lease and recovery SQL is deliberately isolated here. */
final class TaskQueueRepository{
 public function __construct(private mysqli$db){} public function begin():void{$this->db->begin_transaction();}public function commit():void{$this->db->commit();}public function rollback():void{$this->db->rollback();}
 public function lockNextAsyncRespond():?array{$sql="SELECT t.*,s.id_ step_id,s.status step_status,s.step_type,s.agent_key,s.lock_version step_lock,s.input_json,s.model_id step_model FROM Tasks t JOIN TaskSteps s ON s.task_id_=t.id_ AND s.step_key='respond' WHERE t.status='ready' AND s.status='ready' AND COALESCE(t.scheduled_at,NOW(6))<=NOW(6) AND JSON_UNQUOTE(JSON_EXTRACT(s.input_json,'$.execution_mode'))='async' AND NOT EXISTS(SELECT 1 FROM TaskExecutions e WHERE e.task_id_=t.id_ AND e.status IN ('queued','running','waiting')) ORDER BY CASE t.priority WHEN 'urgent' THEN 1 WHEN 'high' THEN 2 WHEN 'normal' THEN 3 ELSE 4 END,COALESCE(t.scheduled_at,t.created_at),t.created_at,t.id_ LIMIT 1 FOR UPDATE SKIP LOCKED";$r=$this->db->query($sql);if(!$r)throw new RuntimeException('queue_select_failed');return$r->fetch_assoc()?:null;}
 public function dependenciesSatisfied(int$id):bool{$s=$this->p("SELECT COUNT(*) c FROM TaskDependencies d JOIN Tasks r ON r.id_=d.depends_on_task_id_ WHERE d.task_id_=? AND NOT(CASE d.condition WHEN 'terminal_any' THEN r.status IN ('completed','failed','cancelled') ELSE r.status='completed' END)");$s->bind_param('i',$id);$this->x($s);$ok=(int)$s->get_result()->fetch_assoc()['c']===0;$s->close();return$ok;}
 public function createClaim(array$t,string$worker,string$token,int$lease,string$trace):array{$step=(int)$t['step_id'];$s=$this->p('SELECT COALESCE(MAX(attempt_number),0)+1 n FROM TaskExecutions WHERE step_id_=?');$s->bind_param('i',$step);$this->x($s);$attempt=(int)$s->get_result()->fetch_assoc()['n'];$s->close();if($attempt>(int)$t['max_attempts'])throw new TaskTransitionException('attempt_limit');$input=json_decode((string)$t['input_json'],true)?:[];$model=(string)($input['model_id']??$t['step_model']??'');$s=$this->p("INSERT INTO TaskExecutions(task_id_,step_id_,trace_id,attempt_number,agent_key,model_id,status,worker_id,lease_token,lease_expires_at,started_at,heartbeat_at) VALUES(?,?,?,?,'chat_main',?,'running',?,?,DATE_ADD(NOW(6),INTERVAL ? SECOND),NOW(6),NOW(6))");$task=(int)$t['id_'];$s->bind_param('iisisssi',$task,$step,$trace,$attempt,$model,$worker,$token,$lease);$this->x($s);$execution=(int)$this->db->insert_id;$s->close();$s=$this->p("UPDATE Tasks SET status='running',started_at=COALESCE(started_at,NOW(6)),last_heartbeat_at=NOW(6),current_step_id_=?,attempt_count=?,lock_version=lock_version+1 WHERE id_=? AND status='ready'");$s->bind_param('iii',$step,$attempt,$task);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('claim_lost');$s->close();$s=$this->p("UPDATE TaskSteps SET status='running',started_at=COALESCE(started_at,NOW(6)),attempt_count=?,lock_version=lock_version+1 WHERE id_=? AND status='ready'");$s->bind_param('ii',$attempt,$step);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('claim_lost');$s->close();$this->event($task,$step,$execution,'execution_started','ready','running','Worker reclamó la ejecución.');return['execution_id'=>$execution,'task_id'=>$task,'step_id'=>$step,'step_type'=>(string)$t['step_type'],'agent_key'=>(string)$t['agent_key'],'user_id'=>(int)$t['user_id_'],'session_id'=>(int)$t['session_id_'],'project_id'=>isset($t['project_id_'])?(int)$t['project_id_']:null,'origin_message_id'=>(int)$t['origin_message_id_'],'objective'=>(string)$t['objective'],'trace_id'=>$trace,'attempt_number'=>$attempt,'worker_id'=>$worker,'lease_token'=>$token,'input'=>$input];}
 public function heartbeat(int$e,string$w,string$t,int$l):bool{$s=$this->p("UPDATE TaskExecutions e JOIN Tasks t ON t.id_=e.task_id_ SET e.heartbeat_at=NOW(6),e.lease_expires_at=DATE_ADD(NOW(6),INTERVAL ? SECOND),t.last_heartbeat_at=NOW(6) WHERE e.id_=? AND e.worker_id=? AND e.lease_token=? AND e.status='running'");$s->bind_param('iiss',$l,$e,$w,$t);$this->x($s);$ok=$s->affected_rows===1;$s->close();return$ok;}
 public function ownedRunning(int$e,string$w,string$token):?array{$s=$this->p("SELECT e.*,t.status task_status,t.cancel_requested_at FROM TaskExecutions e JOIN Tasks t ON t.id_=e.task_id_ WHERE e.id_=? AND e.worker_id=? AND e.lease_token=? AND e.status='running' AND e.lease_expires_at>=NOW(6)");$s->bind_param('iss',$e,$w,$token);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return$r?:null;}
 public function finish(array$c,string$status,?int$message,?string$summary,?string$error):bool{$o=$this->ownedRunning($c['execution_id'],$c['worker_id'],$c['lease_token']);if(!$o)return false;$status=in_array($status,['completed','failed','cancelled'],true)?$status:'failed';$s=$this->p("UPDATE TaskExecutions SET status=?,finished_at=NOW(6),error_message=?,lease_expires_at=NULL WHERE id_=? AND worker_id=? AND lease_token=? AND status='running'");$s->bind_param('ssiss',$status,$error,$c['execution_id'],$c['worker_id'],$c['lease_token']);$this->x($s);if($s->affected_rows!==1){$s->close();return false;}$s->close();$s=$this->p("UPDATE TaskSteps SET status=?,completed_at=IF(?='completed',NOW(6),completed_at),progress_percent=IF(?='completed',100,progress_percent),error_message=?,lock_version=lock_version+1 WHERE id_=? AND status='running'");$s->bind_param('ssssi',$status,$status,$status,$error,$c['step_id']);$this->x($s);$s->close();$code=$status==='failed'?'chat_pipeline_failed':null;$s=$this->p("UPDATE Tasks SET status=?,result_message_id_=COALESCE(?,result_message_id_),result_summary=COALESCE(?,result_summary),error_code=?,error_message=?,completed_at=IF(?='completed',NOW(6),completed_at),cancelled_at=IF(?='cancelled',NOW(6),cancelled_at),progress_percent=IF(?='completed',100,progress_percent),lock_version=lock_version+1 WHERE id_=? AND status='running'");$s->bind_param('sissssssi',$status,$message,$summary,$code,$error,$status,$status,$status,$c['task_id']);$this->x($s);$ok=$s->affected_rows===1;$s->close();if($ok)$this->event($c['task_id'],$c['step_id'],$c['execution_id'],'execution_'.$status,'running',$status,'Ejecución '.$status.'.');return$ok;}
 public function expired(int$limit):array{$s=$this->p("SELECT id_,task_id_,step_id_,trace_id FROM TaskExecutions WHERE status='running' AND lease_expires_at<NOW(6) ORDER BY lease_expires_at LIMIT ? FOR UPDATE SKIP LOCKED");$s->bind_param('i',$limit);$this->x($s);$r=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();return$r;}
 public function abandon(array$e):void{$s=$this->p("UPDATE TaskExecutions SET status='abandoned',finished_at=NOW(6),error_message='Worker lease expired' WHERE id_=? AND status='running' AND lease_expires_at<NOW(6)");$s->bind_param('i',$e['id_']);$this->x($s);$won=$s->affected_rows===1;$s->close();if(!$won)return;$s=$this->p("UPDATE TaskSteps SET status='failed',error_message='Worker lease expired',lock_version=lock_version+1 WHERE id_=? AND status='running'");$s->bind_param('i',$e['step_id_']);$this->x($s);$s->close();$s=$this->p("UPDATE Tasks SET status='failed',error_code='execution_abandoned',error_message='Worker lease expired',lock_version=lock_version+1 WHERE id_=? AND status='running'");$s->bind_param('i',$e['task_id_']);$this->x($s);$s->close();$this->event((int)$e['task_id_'],(int)$e['step_id_'],(int)$e['id_'],'execution_abandoned','running','abandoned','Lease expirado; se requiere retry manual.');}
 private function event(int$t,int$s,int$e,string$k,string$f,string$to,string$summary):void{$q=$this->p("INSERT INTO TaskEvents(task_id_,step_id_,execution_id_,actor_type,event_key,from_status,to_status,summary) VALUES(?,?,?,'worker',?,?,?,?)");$q->bind_param('iiissss',$t,$s,$e,$k,$f,$to,$summary);$this->x($q);$q->close();}private function p(string$q):mysqli_stmt{$s=$this->db->prepare($q);if(!$s)throw new RuntimeException('database_error');return$s;}private function x(mysqli_stmt$s):void{if(!$s->execute())throw new RuntimeException('database_error');}
}
